#[derive(Clone, PartialEq, Debug)]
pub struct SaveEasyRpgData {
    pub version: i32,
    pub codepage: i32,
    pub windows: Vec<SaveEasyRpgWindow>,
}

impl Default for SaveEasyRpgData {
    fn default() -> Self {
        Self::default_for_engine(false)
    }
}

impl SaveEasyRpgData {
    pub fn default_for_engine(_is_2k3: bool) -> Self {
        Self {
            version: 0,
            codepage: 0,
            windows: Vec::new(),
        }
    }

    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x01 => {
                    obj.version = reader.read_int()? as i32;
                }
                0x02 => {
                    obj.codepage = reader.read_int()? as i32;
                }
                0x64 => {
                    let count = reader.read_int()?;
                    obj.windows.clear();
                    for _ in 0..count {
                        let id = reader.read_int()?;
                        let mut item = SaveEasyRpgWindow::read_lcf(reader)?;
                        item.id = id;
                        obj.windows.push(item);
                    }
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        if self.version != _def.version {
            writer.write_int_chunk(0x01, self.version as i32)?;
        }
        if self.codepage != _def.codepage {
            writer.write_int_chunk(0x02, self.codepage as i32)?;
        }
        if !self.windows.is_empty() {
            writer.write_sub_chunk(0x64, |w| {
            w.write_int(self.windows.len() as i32)?;
            for item in &self.windows {
                w.write_int(item.id)?;
                item.write_lcf(w)?;
            }
            Ok(())
        })?;
        }
        writer.write_int(0)?;
        Ok(())
    }
    pub fn write_xml<W: std::io::Write>(&self, writer: &mut crate::xml::XmlWriter<W>) -> Result<(), crate::error::LcfError> {
        writer.begin_element("SaveEasyRpgData")?;
        writer.write_node_int("version", self.version as i32)?;
        writer.write_node_int("codepage", self.codepage as i32)?;
        writer.begin_element("windows")?;
        for item in &self.windows { item.write_xml(writer)?; }
        writer.end_element("windows")?;
        writer.end_element("SaveEasyRpgData")?;
        Ok(())
    }
    pub fn read_xml<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        match reader.next_child()? {
            Some(tag) => Self::read_xml_fields(reader, tag.id.unwrap_or(0), is_2k3),
            None => Ok(Self::default_for_engine(is_2k3)),
        }
    }
    pub fn read_xml_fields<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, id: i32, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default_for_engine(is_2k3);
        loop {
            match reader.next_child()? {
                None => break,
                Some(tag) => match tag.name.as_str() {
                    "version" => obj.version = reader.read_node_int()? as i32,
                    "codepage" => obj.codepage = reader.read_node_int()? as i32,
                    "windows" => {
                        loop {
                            match reader.next_child()? {
                                None => break,
                                Some(item_tag) => obj.windows.push(SaveEasyRpgWindow::read_xml_fields(reader, item_tag.id.unwrap_or(0), is_2k3)?),
                            }
                        }
                    },
                    _ => reader.skip_to_end()?,
                },
            }
        }
        Ok(obj)
    }
}

