#[derive(Clone, PartialEq, Debug)]
pub struct SaveInventory {
    pub party: Vec<i16>,
    pub item_ids: Vec<i16>,
    pub item_counts: Vec<u8>,
    pub item_usage: Vec<u8>,
    pub gold: i32,
    pub timer1_frames: i32,
    pub timer1_active: bool,
    pub timer1_visible: bool,
    pub timer1_battle: bool,
    pub timer2_frames: i32,
    pub timer2_active: bool,
    pub timer2_visible: bool,
    pub timer2_battle: bool,
    pub battles: i32,
    pub defeats: i32,
    pub escapes: i32,
    pub victories: i32,
    pub turns: i32,
    pub steps: i32,
}

impl Default for SaveInventory {
    fn default() -> Self {
        Self::default_for_engine(false)
    }
}

impl SaveInventory {
    pub fn default_for_engine(_is_2k3: bool) -> Self {
        Self {
            party: Vec::new(),
            item_ids: Vec::new(),
            item_counts: Vec::new(),
            item_usage: Vec::new(),
            gold: 0,
            timer1_frames: 0,
            timer1_active: false,
            timer1_visible: false,
            timer1_battle: false,
            timer2_frames: 0,
            timer2_active: false,
            timer2_visible: false,
            timer2_battle: false,
            battles: 0,
            defeats: 0,
            escapes: 0,
            victories: 0,
            turns: 0,
            steps: 0,
        }
    }

    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x01 => { let _ = reader.read_int()?; }
                0x02 => {
                    obj.party = reader.read_vector_i16(chunk.length)?;
                }
                0x0B => { let _ = reader.read_int()?; }
                0x0C => {
                    obj.item_ids = reader.read_vector_i16(chunk.length)?;
                }
                0x0D => {
                    obj.item_counts = reader.read_vector_u8(chunk.length)?;
                }
                0x0E => {
                    obj.item_usage = reader.read_vector_u8(chunk.length)?;
                }
                0x15 => {
                    obj.gold = reader.read_int()? as i32;
                }
                0x17 => {
                    obj.timer1_frames = reader.read_int()? as i32;
                }
                0x18 => {
                    obj.timer1_active = reader.read_bool()?;
                }
                0x19 => {
                    obj.timer1_visible = reader.read_bool()?;
                }
                0x1A => {
                    obj.timer1_battle = reader.read_bool()?;
                }
                0x1B => {
                    obj.timer2_frames = reader.read_int()? as i32;
                }
                0x1C => {
                    obj.timer2_active = reader.read_bool()?;
                }
                0x1D => {
                    obj.timer2_visible = reader.read_bool()?;
                }
                0x1E => {
                    obj.timer2_battle = reader.read_bool()?;
                }
                0x20 => {
                    obj.battles = reader.read_int()? as i32;
                }
                0x21 => {
                    obj.defeats = reader.read_int()? as i32;
                }
                0x22 => {
                    obj.escapes = reader.read_int()? as i32;
                }
                0x23 => {
                    obj.victories = reader.read_int()? as i32;
                }
                0x29 => {
                    obj.turns = reader.read_int()? as i32;
                }
                0x2A => {
                    obj.steps = reader.read_int()? as i32;
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        writer.write_vector_i16_chunk(0x02, &self.party)?;
        writer.write_vector_i16_chunk(0x0C, &self.item_ids)?;
        writer.write_vector_u8_chunk(0x0D, &self.item_counts)?;
        writer.write_vector_u8_chunk(0x0E, &self.item_usage)?;
        if self.gold != _def.gold {
            writer.write_int_chunk(0x15, self.gold as i32)?;
        }
        if self.timer1_frames != _def.timer1_frames {
            writer.write_int_chunk(0x17, self.timer1_frames as i32)?;
        }
        if self.timer1_active != _def.timer1_active {
            writer.write_bool_chunk(0x18, self.timer1_active)?;
        }
        if self.timer1_visible != _def.timer1_visible {
            writer.write_bool_chunk(0x19, self.timer1_visible)?;
        }
        if self.timer1_battle != _def.timer1_battle {
            writer.write_bool_chunk(0x1A, self.timer1_battle)?;
        }
        if self.timer2_frames != _def.timer2_frames {
            writer.write_int_chunk(0x1B, self.timer2_frames as i32)?;
        }
        if self.timer2_active != _def.timer2_active {
            writer.write_bool_chunk(0x1C, self.timer2_active)?;
        }
        if self.timer2_visible != _def.timer2_visible {
            writer.write_bool_chunk(0x1D, self.timer2_visible)?;
        }
        if self.timer2_battle != _def.timer2_battle {
            writer.write_bool_chunk(0x1E, self.timer2_battle)?;
        }
        if self.battles != _def.battles {
            writer.write_int_chunk(0x20, self.battles as i32)?;
        }
        if self.defeats != _def.defeats {
            writer.write_int_chunk(0x21, self.defeats as i32)?;
        }
        if self.escapes != _def.escapes {
            writer.write_int_chunk(0x22, self.escapes as i32)?;
        }
        if self.victories != _def.victories {
            writer.write_int_chunk(0x23, self.victories as i32)?;
        }
        if self.turns != _def.turns {
            writer.write_int_chunk(0x29, self.turns as i32)?;
        }
        if self.steps != _def.steps {
            writer.write_int_chunk(0x2A, self.steps as i32)?;
        }
        writer.write_int(0)?;
        Ok(())
    }
    pub fn write_xml<W: std::io::Write>(&self, writer: &mut crate::xml::XmlWriter<W>) -> Result<(), crate::error::LcfError> {
        writer.begin_element("SaveInventory")?;
        writer.write_node_vector_i16("party", &self.party)?;
        writer.write_node_vector_i16("item_ids", &self.item_ids)?;
        writer.write_node_vector_u8("item_counts", &self.item_counts)?;
        writer.write_node_vector_u8("item_usage", &self.item_usage)?;
        writer.write_node_int("gold", self.gold as i32)?;
        writer.write_node_int("timer1_frames", self.timer1_frames as i32)?;
        writer.write_node_bool("timer1_active", self.timer1_active)?;
        writer.write_node_bool("timer1_visible", self.timer1_visible)?;
        writer.write_node_bool("timer1_battle", self.timer1_battle)?;
        writer.write_node_int("timer2_frames", self.timer2_frames as i32)?;
        writer.write_node_bool("timer2_active", self.timer2_active)?;
        writer.write_node_bool("timer2_visible", self.timer2_visible)?;
        writer.write_node_bool("timer2_battle", self.timer2_battle)?;
        writer.write_node_int("battles", self.battles as i32)?;
        writer.write_node_int("defeats", self.defeats as i32)?;
        writer.write_node_int("escapes", self.escapes as i32)?;
        writer.write_node_int("victories", self.victories as i32)?;
        writer.write_node_int("turns", self.turns as i32)?;
        writer.write_node_int("steps", self.steps as i32)?;
        writer.end_element("SaveInventory")?;
        Ok(())
    }
    pub fn read_xml<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        match reader.next_child()? {
            Some(tag) => Self::read_xml_fields(reader, tag.id.unwrap_or(0), is_2k3),
            None => Ok(Self::default_for_engine(is_2k3)),
        }
    }
    pub fn read_xml_fields<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, id: i32, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default_for_engine(is_2k3);
        loop {
            match reader.next_child()? {
                None => break,
                Some(tag) => match tag.name.as_str() {
                    "party" => obj.party = reader.read_node_vector_i16()?,
                    "item_ids" => obj.item_ids = reader.read_node_vector_i16()?,
                    "item_counts" => obj.item_counts = reader.read_node_vector_u8()?,
                    "item_usage" => obj.item_usage = reader.read_node_vector_u8()?,
                    "gold" => obj.gold = reader.read_node_int()? as i32,
                    "timer1_frames" => obj.timer1_frames = reader.read_node_int()? as i32,
                    "timer1_active" => obj.timer1_active = reader.read_node_bool()?,
                    "timer1_visible" => obj.timer1_visible = reader.read_node_bool()?,
                    "timer1_battle" => obj.timer1_battle = reader.read_node_bool()?,
                    "timer2_frames" => obj.timer2_frames = reader.read_node_int()? as i32,
                    "timer2_active" => obj.timer2_active = reader.read_node_bool()?,
                    "timer2_visible" => obj.timer2_visible = reader.read_node_bool()?,
                    "timer2_battle" => obj.timer2_battle = reader.read_node_bool()?,
                    "battles" => obj.battles = reader.read_node_int()? as i32,
                    "defeats" => obj.defeats = reader.read_node_int()? as i32,
                    "escapes" => obj.escapes = reader.read_node_int()? as i32,
                    "victories" => obj.victories = reader.read_node_int()? as i32,
                    "turns" => obj.turns = reader.read_node_int()? as i32,
                    "steps" => obj.steps = reader.read_node_int()? as i32,
                    _ => reader.skip_to_end()?,
                },
            }
        }
        Ok(obj)
    }
}

