#[derive(Clone, PartialEq, Debug)]
pub struct SaveMapInfo {
    pub position_x: i32,
    pub position_y: i32,
    pub encounter_steps: i32,
    pub chipset_id: i32,
    pub events: Vec<SaveMapEvent>,
    pub lower_tiles: Vec<u8>,
    pub upper_tiles: Vec<u8>,
    pub parallax_name: DBString,
    pub parallax_horz: bool,
    pub parallax_vert: bool,
    pub parallax_horz_auto: bool,
    pub parallax_horz_speed: i32,
    pub parallax_vert_auto: bool,
    pub parallax_vert_speed: i32,
}

impl Default for SaveMapInfo {
    fn default() -> Self {
        Self::default_for_engine(false)
    }
}

impl SaveMapInfo {
    pub fn default_for_engine(_is_2k3: bool) -> Self {
        Self {
            position_x: 0,
            position_y: 0,
            encounter_steps: -1,
            chipset_id: 0,
            events: Vec::new(),
            lower_tiles: Vec::new(),
            upper_tiles: Vec::new(),
            parallax_name: DBString::default(),
            parallax_horz: false,
            parallax_vert: false,
            parallax_horz_auto: false,
            parallax_horz_speed: 0,
            parallax_vert_auto: false,
            parallax_vert_speed: 0,
        }
    }

    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x01 => {
                    obj.position_x = reader.read_int()? as i32;
                }
                0x02 => {
                    obj.position_y = reader.read_int()? as i32;
                }
                0x03 => {
                    obj.encounter_steps = reader.read_int()? as i32;
                }
                0x05 => {
                    obj.chipset_id = reader.read_int()? as i32;
                }
                0x0B => {
                    let count = reader.read_int()?;
                    obj.events.clear();
                    for _ in 0..count {
                        let id = reader.read_int()?;
                        let mut item = SaveMapEvent::read_lcf(reader)?;
                        item.id = id;
                        obj.events.push(item);
                    }
                }
                0x15 => {
                    obj.lower_tiles = reader.read_vector_u8(chunk.length)?;
                }
                0x16 => {
                    obj.upper_tiles = reader.read_vector_u8(chunk.length)?;
                }
                0x20 => {
                    obj.parallax_name = reader.read_string(chunk.length)?;
                }
                0x21 => {
                    obj.parallax_horz = reader.read_bool()?;
                }
                0x22 => {
                    obj.parallax_vert = reader.read_bool()?;
                }
                0x23 => {
                    obj.parallax_horz_auto = reader.read_bool()?;
                }
                0x24 => {
                    obj.parallax_horz_speed = reader.read_int()? as i32;
                }
                0x25 => {
                    obj.parallax_vert_auto = reader.read_bool()?;
                }
                0x26 => {
                    obj.parallax_vert_speed = reader.read_int()? as i32;
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        if self.position_x != _def.position_x {
            writer.write_int_chunk(0x01, self.position_x as i32)?;
        }
        if self.position_y != _def.position_y {
            writer.write_int_chunk(0x02, self.position_y as i32)?;
        }
        if self.encounter_steps != _def.encounter_steps {
            writer.write_int_chunk(0x03, self.encounter_steps as i32)?;
        }
        if self.chipset_id != _def.chipset_id {
            writer.write_int_chunk(0x05, self.chipset_id as i32)?;
        }
        writer.write_sub_chunk(0x0B, |w| {
            w.write_int(self.events.len() as i32)?;
            for item in &self.events {
                w.write_int(item.id)?;
                item.write_lcf(w)?;
            }
            Ok(())
        })?;
        writer.write_vector_u8_chunk(0x15, &self.lower_tiles)?;
        writer.write_vector_u8_chunk(0x16, &self.upper_tiles)?;
        if self.parallax_name != _def.parallax_name {
            writer.write_dbstring_chunk(0x20, &self.parallax_name)?;
        }
        if self.parallax_horz != _def.parallax_horz {
            writer.write_bool_chunk(0x21, self.parallax_horz)?;
        }
        if self.parallax_vert != _def.parallax_vert {
            writer.write_bool_chunk(0x22, self.parallax_vert)?;
        }
        if self.parallax_horz_auto != _def.parallax_horz_auto {
            writer.write_bool_chunk(0x23, self.parallax_horz_auto)?;
        }
        if self.parallax_horz_speed != _def.parallax_horz_speed {
            writer.write_int_chunk(0x24, self.parallax_horz_speed as i32)?;
        }
        if self.parallax_vert_auto != _def.parallax_vert_auto {
            writer.write_bool_chunk(0x25, self.parallax_vert_auto)?;
        }
        if self.parallax_vert_speed != _def.parallax_vert_speed {
            writer.write_int_chunk(0x26, self.parallax_vert_speed as i32)?;
        }
        writer.write_int(0)?;
        Ok(())
    }
    pub fn write_xml<W: std::io::Write>(&self, writer: &mut crate::xml::XmlWriter<W>) -> Result<(), crate::error::LcfError> {
        writer.begin_element("SaveMapInfo")?;
        writer.write_node_int("position_x", self.position_x as i32)?;
        writer.write_node_int("position_y", self.position_y as i32)?;
        writer.write_node_int("encounter_steps", self.encounter_steps as i32)?;
        writer.write_node_int("chipset_id", self.chipset_id as i32)?;
        writer.begin_element("events")?;
        for item in &self.events { item.write_xml(writer)?; }
        writer.end_element("events")?;
        writer.write_node_vector_u8("lower_tiles", &self.lower_tiles)?;
        writer.write_node_vector_u8("upper_tiles", &self.upper_tiles)?;
        writer.write_node_dbstring("parallax_name", &self.parallax_name)?;
        writer.write_node_bool("parallax_horz", self.parallax_horz)?;
        writer.write_node_bool("parallax_vert", self.parallax_vert)?;
        writer.write_node_bool("parallax_horz_auto", self.parallax_horz_auto)?;
        writer.write_node_int("parallax_horz_speed", self.parallax_horz_speed as i32)?;
        writer.write_node_bool("parallax_vert_auto", self.parallax_vert_auto)?;
        writer.write_node_int("parallax_vert_speed", self.parallax_vert_speed as i32)?;
        writer.end_element("SaveMapInfo")?;
        Ok(())
    }
    pub fn read_xml<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        match reader.next_child()? {
            Some(tag) => Self::read_xml_fields(reader, tag.id.unwrap_or(0), is_2k3),
            None => Ok(Self::default_for_engine(is_2k3)),
        }
    }
    pub fn read_xml_fields<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, id: i32, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default_for_engine(is_2k3);
        loop {
            match reader.next_child()? {
                None => break,
                Some(tag) => match tag.name.as_str() {
                    "position_x" => obj.position_x = reader.read_node_int()? as i32,
                    "position_y" => obj.position_y = reader.read_node_int()? as i32,
                    "encounter_steps" => obj.encounter_steps = reader.read_node_int()? as i32,
                    "chipset_id" => obj.chipset_id = reader.read_node_int()? as i32,
                    "events" => {
                        loop {
                            match reader.next_child()? {
                                None => break,
                                Some(item_tag) => obj.events.push(SaveMapEvent::read_xml_fields(reader, item_tag.id.unwrap_or(0), is_2k3)?),
                            }
                        }
                    },
                    "lower_tiles" => obj.lower_tiles = reader.read_node_vector_u8()?,
                    "upper_tiles" => obj.upper_tiles = reader.read_node_vector_u8()?,
                    "parallax_name" => obj.parallax_name = reader.read_node_dbstring()?,
                    "parallax_horz" => obj.parallax_horz = reader.read_node_bool()?,
                    "parallax_vert" => obj.parallax_vert = reader.read_node_bool()?,
                    "parallax_horz_auto" => obj.parallax_horz_auto = reader.read_node_bool()?,
                    "parallax_horz_speed" => obj.parallax_horz_speed = reader.read_node_int()? as i32,
                    "parallax_vert_auto" => obj.parallax_vert_auto = reader.read_node_bool()?,
                    "parallax_vert_speed" => obj.parallax_vert_speed = reader.read_node_int()? as i32,
                    _ => reader.skip_to_end()?,
                },
            }
        }
        Ok(obj)
    }
}

