    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x01 => {
                    obj.active = reader.read_bool()?;
                }
                0x0B => {
                    obj.map_id = reader.read_int()? as i32;
                }
                0x0C => {
                    obj.position_x = reader.read_int()? as i32;
                }
                0x0D => {
                    obj.position_y = reader.read_int()? as i32;
                }
                0x15 => {
                    obj.direction = reader.read_int()? as i32;
                }
                0x16 => {
                    obj.facing = reader.read_int()? as i32;
                }
                0x17 => {
                    obj.anim_frame = reader.read_int()? as i32;
                }
                0x18 => {
                    obj.transparency = reader.read_int()? as i32;
                }
                0x1F => {
                    obj.remaining_step = reader.read_int()? as i32;
                }
                0x20 => {
                    obj.move_frequency = reader.read_int()? as i32;
                }
                0x21 => {
                    obj.layer = reader.read_int()? as i32;
                }
                0x22 => {
                    obj.overlap_forbidden = reader.read_bool()?;
                }
                0x23 => {
                    obj.animation_type = reader.read_int()? as i32;
                }
                0x24 => {
                    obj.lock_facing = reader.read_bool()?;
                }
                0x25 => {
                    obj.move_speed = reader.read_int()? as i32;
                }
                0x29 => {
                    obj.move_route = MoveRoute::read_lcf(reader)?;
                }
                0x2A => {
                    obj.move_route_overwrite = reader.read_bool()?;
                }
                0x2B => {
                    obj.move_route_index = reader.read_int()? as i32;
                }
                0x2C => {
                    obj.move_route_finished = reader.read_bool()?;
                }
                0x2E => {
                    obj.sprite_hidden = reader.read_bool()?;
                }
                0x2F => {
                    obj.move_route_through = reader.read_bool()?;
                }
                0x30 => {
                    obj.anim_paused = reader.read_int()? as i32;
                }
                0x33 => {
                    obj.through = reader.read_bool()?;
                }
                0x34 => {
                    obj.stop_count = reader.read_int()? as i32;
                }
                0x35 => {
                    obj.anim_count = reader.read_int()? as i32;
                }
                0x36 => {
                    obj.max_stop_count = reader.read_int()? as i32;
                }
                0x3D => {
                    obj.jumping = reader.read_bool()?;
                }
                0x3E => {
                    obj.begin_jump_x = reader.read_int()? as i32;
                }
                0x3F => {
                    obj.begin_jump_y = reader.read_int()? as i32;
                }
                0x47 => {
                    obj.pause = reader.read_bool()?;
                }
                0x48 => {
                    obj.flying = reader.read_bool()?;
                }
                0x49 => {
                    obj.sprite_name = reader.read_string(chunk.length)?;
                }
                0x4A => {
                    obj.sprite_id = reader.read_int()? as i32;
                }
                0x4B => {
                    obj.processed = reader.read_bool()?;
                }
                0x51 => {
                    obj.flash_red = reader.read_int()? as i32;
                }
                0x52 => {
                    obj.flash_green = reader.read_int()? as i32;
                }
                0x53 => {
                    obj.flash_blue = reader.read_int()? as i32;
                }
                0x54 => {
                    obj.flash_current_level = reader.read_f64()?;
                }
                0x55 => {
                    obj.flash_time_left = reader.read_int()? as i32;
                }
                0x65 => {
                    obj.boarding = reader.read_bool()?;
                }
                0x66 => {
                    obj.aboard = reader.read_bool()?;
                }
                0x67 => {
                    obj.vehicle = reader.read_int()? as i32;
                }
                0x68 => {
                    obj.unboarding = reader.read_bool()?;
                }
                0x69 => {
                    obj.preboard_move_speed = reader.read_int()? as i32;
                }
                0x6C => {
                    obj.menu_calling = reader.read_bool()?;
                }
                0x6F => {
                    obj.pan_state = reader.read_int()? as i32;
                }
                0x70 => {
                    obj.pan_current_x = reader.read_int()? as i32;
                }
                0x71 => {
                    obj.pan_current_y = reader.read_int()? as i32;
                }
                0x72 => {
                    obj.pan_finish_x = reader.read_int()? as i32;
                }
                0x73 => {
                    obj.pan_finish_y = reader.read_int()? as i32;
                }
                0x79 => {
                    obj.pan_speed = reader.read_int()? as i32;
                }
                0x7C => {
                    obj.total_encounter_rate = reader.read_int()? as i32;
                }
                0x7D => {
                    obj.encounter_calling = reader.read_bool()?;
                }
                0x83 => {
                    obj.map_save_count = reader.read_int()? as i32;
                }
                0x84 => {
                    obj.database_save_count = reader.read_int()? as i32;
                }
                0x8D => {
                    obj.maniac_horizontal_pan_speed = reader.read_f64()?;
                }
                0x8E => {
                    obj.maniac_vertical_pan_speed = reader.read_f64()?;
                }
                0xC9 => {
                    obj.easyrpg_move_failure_count = reader.read_int()? as i32;
                }
                0xCA => {
                    obj.easyrpg_clone_map_id = reader.read_u32_le()?;
                }
                0xCB => {
                    obj.easyrpg_clone_event_id = reader.read_u32_le()?;
                }
                0xCC => {
                    obj.easyrpg_runtime_flags = reader.read_flags(chunk.length)?;
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        if self.active != _def.active {
            writer.write_bool_chunk(0x01, self.active)?;
        }
        writer.write_int_chunk(0x0B, self.map_id as i32)?;
        writer.write_int_chunk(0x0C, self.position_x as i32)?;
        writer.write_int_chunk(0x0D, self.position_y as i32)?;
        writer.write_int_chunk(0x15, self.direction as i32)?;
        writer.write_int_chunk(0x16, self.facing as i32)?;
        if self.anim_frame != _def.anim_frame {
            writer.write_int_chunk(0x17, self.anim_frame as i32)?;
        }
        if self.transparency != _def.transparency {
            writer.write_int_chunk(0x18, self.transparency as i32)?;
        }
        if self.remaining_step != _def.remaining_step {
            writer.write_int_chunk(0x1F, self.remaining_step as i32)?;
        }
        if self.move_frequency != _def.move_frequency {
            writer.write_int_chunk(0x20, self.move_frequency as i32)?;
        }
        writer.write_int_chunk(0x21, self.layer as i32)?;
        if self.overlap_forbidden != _def.overlap_forbidden {
            writer.write_bool_chunk(0x22, self.overlap_forbidden)?;
        }
        writer.write_int_chunk(0x23, self.animation_type as i32)?;
        if self.lock_facing != _def.lock_facing {
            writer.write_bool_chunk(0x24, self.lock_facing)?;
        }
        writer.write_int_chunk(0x25, self.move_speed as i32)?;
        writer.write_sub_chunk(0x29, |w| self.move_route.write_lcf(w))?;
        if self.move_route_overwrite != _def.move_route_overwrite {
            writer.write_bool_chunk(0x2A, self.move_route_overwrite)?;
        }
        if self.move_route_index != _def.move_route_index {
            writer.write_int_chunk(0x2B, self.move_route_index as i32)?;
        }
        if self.move_route_finished != _def.move_route_finished {
            writer.write_bool_chunk(0x2C, self.move_route_finished)?;
        }
        if self.sprite_hidden != _def.sprite_hidden {
            writer.write_bool_chunk(0x2E, self.sprite_hidden)?;
        }
        if self.move_route_through != _def.move_route_through {
            writer.write_bool_chunk(0x2F, self.move_route_through)?;
        }
        if self.anim_paused != _def.anim_paused {
            writer.write_int_chunk(0x30, self.anim_paused as i32)?;
        }
        if self.through != _def.through {
            writer.write_bool_chunk(0x33, self.through)?;
        }
        if self.stop_count != _def.stop_count {
            writer.write_int_chunk(0x34, self.stop_count as i32)?;
        }
        if self.anim_count != _def.anim_count {
            writer.write_int_chunk(0x35, self.anim_count as i32)?;
        }
        if self.max_stop_count != _def.max_stop_count {
            writer.write_int_chunk(0x36, self.max_stop_count as i32)?;
        }
        if self.jumping != _def.jumping {
            writer.write_bool_chunk(0x3D, self.jumping)?;
        }
        if self.begin_jump_x != _def.begin_jump_x {
            writer.write_int_chunk(0x3E, self.begin_jump_x as i32)?;
        }
        if self.begin_jump_y != _def.begin_jump_y {
            writer.write_int_chunk(0x3F, self.begin_jump_y as i32)?;
        }
        if self.pause != _def.pause {
            writer.write_bool_chunk(0x47, self.pause)?;
        }
        if self.flying != _def.flying {
            writer.write_bool_chunk(0x48, self.flying)?;
        }
        if self.sprite_name != _def.sprite_name {
            writer.write_dbstring_chunk(0x49, &self.sprite_name)?;
        }
        if self.sprite_id != _def.sprite_id {
            writer.write_int_chunk(0x4A, self.sprite_id as i32)?;
        }
        if self.processed != _def.processed {
            writer.write_bool_chunk(0x4B, self.processed)?;
        }
        if self.flash_red != _def.flash_red {
            writer.write_int_chunk(0x51, self.flash_red as i32)?;
        }
        if self.flash_green != _def.flash_green {
            writer.write_int_chunk(0x52, self.flash_green as i32)?;
        }
        if self.flash_blue != _def.flash_blue {
            writer.write_int_chunk(0x53, self.flash_blue as i32)?;
        }
        if (self.flash_current_level - _def.flash_current_level).abs() > f64::EPSILON {
            writer.write_sub_chunk(0x54, |w| w.write_f64(self.flash_current_level))?;
        }
        if self.flash_time_left != _def.flash_time_left {
            writer.write_int_chunk(0x55, self.flash_time_left as i32)?;
        }
        if self.boarding != _def.boarding {
            writer.write_bool_chunk(0x65, self.boarding)?;
        }
        if self.aboard != _def.aboard {
            writer.write_bool_chunk(0x66, self.aboard)?;
        }
        if self.vehicle != _def.vehicle {
            writer.write_int_chunk(0x67, self.vehicle as i32)?;
        }
        if self.unboarding != _def.unboarding {
            writer.write_bool_chunk(0x68, self.unboarding)?;
        }
        if self.preboard_move_speed != _def.preboard_move_speed {
            writer.write_int_chunk(0x69, self.preboard_move_speed as i32)?;
        }
        if self.menu_calling != _def.menu_calling {
            writer.write_bool_chunk(0x6C, self.menu_calling)?;
        }
        if self.pan_state != _def.pan_state {
            writer.write_int_chunk(0x6F, self.pan_state as i32)?;
        }
        if self.pan_current_x != _def.pan_current_x {
            writer.write_int_chunk(0x70, self.pan_current_x as i32)?;
        }
        if self.pan_current_y != _def.pan_current_y {
            writer.write_int_chunk(0x71, self.pan_current_y as i32)?;
        }
        if self.pan_finish_x != _def.pan_finish_x {
            writer.write_int_chunk(0x72, self.pan_finish_x as i32)?;
        }
        if self.pan_finish_y != _def.pan_finish_y {
            writer.write_int_chunk(0x73, self.pan_finish_y as i32)?;
        }
        if self.pan_speed != _def.pan_speed {
            writer.write_int_chunk(0x79, self.pan_speed as i32)?;
        }
        if self.total_encounter_rate != _def.total_encounter_rate {
            writer.write_int_chunk(0x7C, self.total_encounter_rate as i32)?;
        }
        if self.encounter_calling != _def.encounter_calling {
            writer.write_bool_chunk(0x7D, self.encounter_calling)?;
        }
        if self.map_save_count != _def.map_save_count {
            writer.write_int_chunk(0x83, self.map_save_count as i32)?;
        }
        if self.database_save_count != _def.database_save_count {
            writer.write_int_chunk(0x84, self.database_save_count as i32)?;
        }
        if (self.maniac_horizontal_pan_speed - _def.maniac_horizontal_pan_speed).abs() > f64::EPSILON {
            writer.write_sub_chunk(0x8D, |w| w.write_f64(self.maniac_horizontal_pan_speed))?;
        }
        if (self.maniac_vertical_pan_speed - _def.maniac_vertical_pan_speed).abs() > f64::EPSILON {
            writer.write_sub_chunk(0x8E, |w| w.write_f64(self.maniac_vertical_pan_speed))?;
        }
        if self.easyrpg_move_failure_count != _def.easyrpg_move_failure_count {
            writer.write_int_chunk(0xC9, self.easyrpg_move_failure_count as i32)?;
        }
        if self.easyrpg_clone_map_id != _def.easyrpg_clone_map_id {
            writer.write_int_chunk(0xCA, self.easyrpg_clone_map_id as i32)?;
        }
        if self.easyrpg_clone_event_id != _def.easyrpg_clone_event_id {
            writer.write_int_chunk(0xCB, self.easyrpg_clone_event_id as i32)?;
        }
        if self.easyrpg_runtime_flags != _def.easyrpg_runtime_flags {
            writer.write_flags_chunk(0xCC, self.easyrpg_runtime_flags, writer.is_2k3())?;
        }
        writer.write_int(0)?;
        Ok(())
    }
