#[derive(Clone, PartialEq, Debug)]
pub struct SaveTarget {
    pub id: i32,
    pub map_id: i32,
    pub map_x: i32,
    pub map_y: i32,
    pub switch_on: bool,
    pub switch_id: i32,
}

impl Default for SaveTarget {
    fn default() -> Self {
        Self::default_for_engine(false)
    }
}

impl SaveTarget {
    pub fn default_for_engine(_is_2k3: bool) -> Self {
        Self {
            id: 0,
            map_id: 0,
            map_x: 0,
            map_y: 0,
            switch_on: false,
            switch_id: 0,
        }
    }

    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x01 => {
                    obj.map_id = reader.read_int()? as i32;
                }
                0x02 => {
                    obj.map_x = reader.read_int()? as i32;
                }
                0x03 => {
                    obj.map_y = reader.read_int()? as i32;
                }
                0x04 => {
                    obj.switch_on = reader.read_bool()?;
                }
                0x05 => {
                    obj.switch_id = reader.read_int()? as i32;
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        if self.map_id != _def.map_id {
            writer.write_int_chunk(0x01, self.map_id as i32)?;
        }
        if self.map_x != _def.map_x {
            writer.write_int_chunk(0x02, self.map_x as i32)?;
        }
        if self.map_y != _def.map_y {
            writer.write_int_chunk(0x03, self.map_y as i32)?;
        }
        if self.switch_on != _def.switch_on {
            writer.write_bool_chunk(0x04, self.switch_on)?;
        }
        if self.switch_id != _def.switch_id {
            writer.write_int_chunk(0x05, self.switch_id as i32)?;
        }
        writer.write_int(0)?;
        Ok(())
    }
    pub fn write_xml<W: std::io::Write>(&self, writer: &mut crate::xml::XmlWriter<W>) -> Result<(), crate::error::LcfError> {
        writer.begin_element_with_id("SaveTarget", self.id)?;
        writer.write_node_int("map_id", self.map_id as i32)?;
        writer.write_node_int("map_x", self.map_x as i32)?;
        writer.write_node_int("map_y", self.map_y as i32)?;
        writer.write_node_bool("switch_on", self.switch_on)?;
        writer.write_node_int("switch_id", self.switch_id as i32)?;
        writer.end_element("SaveTarget")?;
        Ok(())
    }
    pub fn read_xml<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        match reader.next_child()? {
            Some(tag) => Self::read_xml_fields(reader, tag.id.unwrap_or(0), is_2k3),
            None => Ok(Self::default_for_engine(is_2k3)),
        }
    }
    pub fn read_xml_fields<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, id: i32, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default_for_engine(is_2k3);
        obj.id = id;
        loop {
            match reader.next_child()? {
                None => break,
                Some(tag) => match tag.name.as_str() {
                    "map_id" => obj.map_id = reader.read_node_int()? as i32,
                    "map_x" => obj.map_x = reader.read_node_int()? as i32,
                    "map_y" => obj.map_y = reader.read_node_int()? as i32,
                    "switch_on" => obj.switch_on = reader.read_node_bool()?,
                    "switch_id" => obj.switch_id = reader.read_node_int()? as i32,
                    _ => reader.skip_to_end()?,
                },
            }
        }
        Ok(obj)
    }
}

#[derive(Clone, PartialEq, Debug)]
pub struct SaveTitle {
    pub timestamp: f64,
    pub hero_name: DBString,
    pub hero_level: i32,
    pub hero_hp: i32,
    pub face1_name: DBString,
    pub face1_id: i32,
    pub face2_name: DBString,
    pub face2_id: i32,
    pub face3_name: DBString,
    pub face3_id: i32,
    pub face4_name: DBString,
    pub face4_id: i32,
}

impl Default for SaveTitle {
    fn default() -> Self {
        Self::default_for_engine(false)
    }
}

impl SaveTitle {
    pub fn default_for_engine(_is_2k3: bool) -> Self {
        Self {
            timestamp: 0.0,
            hero_name: DBString::default(),
            hero_level: 0,
            hero_hp: 0,
            face1_name: DBString::default(),
            face1_id: 0,
            face2_name: DBString::default(),
            face2_id: 0,
            face3_name: DBString::default(),
            face3_id: 0,
            face4_name: DBString::default(),
            face4_id: 0,
        }
    }

    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x01 => {
                    obj.timestamp = reader.read_f64()?;
                }
                0x0B => {
                    obj.hero_name = reader.read_string(chunk.length)?;
                }
                0x0C => {
                    obj.hero_level = reader.read_int()? as i32;
                }
                0x0D => {
                    obj.hero_hp = reader.read_int()? as i32;
                }
                0x15 => {
                    obj.face1_name = reader.read_string(chunk.length)?;
                }
                0x16 => {
                    obj.face1_id = reader.read_int()? as i32;
                }
                0x17 => {
                    obj.face2_name = reader.read_string(chunk.length)?;
                }
                0x18 => {
                    obj.face2_id = reader.read_int()? as i32;
                }
                0x19 => {
                    obj.face3_name = reader.read_string(chunk.length)?;
                }
                0x1A => {
                    obj.face3_id = reader.read_int()? as i32;
                }
                0x1B => {
                    obj.face4_name = reader.read_string(chunk.length)?;
                }
                0x1C => {
                    obj.face4_id = reader.read_int()? as i32;
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        if (self.timestamp - _def.timestamp).abs() > f64::EPSILON {
            writer.write_sub_chunk(0x01, |w| w.write_f64(self.timestamp))?;
        }
        if self.hero_name != _def.hero_name {
            writer.write_dbstring_chunk(0x0B, &self.hero_name)?;
        }
        if self.hero_level != _def.hero_level {
            writer.write_int_chunk(0x0C, self.hero_level as i32)?;
        }
        if self.hero_hp != _def.hero_hp {
            writer.write_int_chunk(0x0D, self.hero_hp as i32)?;
        }
        if self.face1_name != _def.face1_name {
            writer.write_dbstring_chunk(0x15, &self.face1_name)?;
        }
        if self.face1_id != _def.face1_id {
            writer.write_int_chunk(0x16, self.face1_id as i32)?;
        }
        if self.face2_name != _def.face2_name {
            writer.write_dbstring_chunk(0x17, &self.face2_name)?;
        }
        if self.face2_id != _def.face2_id {
            writer.write_int_chunk(0x18, self.face2_id as i32)?;
        }
        if self.face3_name != _def.face3_name {
            writer.write_dbstring_chunk(0x19, &self.face3_name)?;
        }
        if self.face3_id != _def.face3_id {
            writer.write_int_chunk(0x1A, self.face3_id as i32)?;
        }
        if self.face4_name != _def.face4_name {
            writer.write_dbstring_chunk(0x1B, &self.face4_name)?;
        }
        if self.face4_id != _def.face4_id {
            writer.write_int_chunk(0x1C, self.face4_id as i32)?;
        }
        writer.write_int(0)?;
        Ok(())
    }
    pub fn write_xml<W: std::io::Write>(&self, writer: &mut crate::xml::XmlWriter<W>) -> Result<(), crate::error::LcfError> {
        writer.begin_element("SaveTitle")?;
        writer.write_node_f64("timestamp", self.timestamp)?;
        writer.write_node_dbstring("hero_name", &self.hero_name)?;
        writer.write_node_int("hero_level", self.hero_level as i32)?;
        writer.write_node_int("hero_hp", self.hero_hp as i32)?;
        writer.write_node_dbstring("face1_name", &self.face1_name)?;
        writer.write_node_int("face1_id", self.face1_id as i32)?;
        writer.write_node_dbstring("face2_name", &self.face2_name)?;
        writer.write_node_int("face2_id", self.face2_id as i32)?;
        writer.write_node_dbstring("face3_name", &self.face3_name)?;
        writer.write_node_int("face3_id", self.face3_id as i32)?;
        writer.write_node_dbstring("face4_name", &self.face4_name)?;
        writer.write_node_int("face4_id", self.face4_id as i32)?;
        writer.end_element("SaveTitle")?;
        Ok(())
    }
    pub fn read_xml<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        match reader.next_child()? {
            Some(tag) => Self::read_xml_fields(reader, tag.id.unwrap_or(0), is_2k3),
            None => Ok(Self::default_for_engine(is_2k3)),
        }
    }
    pub fn read_xml_fields<R: std::io::BufRead>(reader: &mut crate::xml::XmlReader<R>, id: i32, is_2k3: bool) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default_for_engine(is_2k3);
        loop {
            match reader.next_child()? {
                None => break,
                Some(tag) => match tag.name.as_str() {
                    "timestamp" => obj.timestamp = reader.read_node_f64()?,
                    "hero_name" => obj.hero_name = reader.read_node_dbstring()?,
                    "hero_level" => obj.hero_level = reader.read_node_int()? as i32,
                    "hero_hp" => obj.hero_hp = reader.read_node_int()? as i32,
                    "face1_name" => obj.face1_name = reader.read_node_dbstring()?,
                    "face1_id" => obj.face1_id = reader.read_node_int()? as i32,
                    "face2_name" => obj.face2_name = reader.read_node_dbstring()?,
                    "face2_id" => obj.face2_id = reader.read_node_int()? as i32,
                    "face3_name" => obj.face3_name = reader.read_node_dbstring()?,
                    "face3_id" => obj.face3_id = reader.read_node_int()? as i32,
                    "face4_name" => obj.face4_name = reader.read_node_dbstring()?,
                    "face4_id" => obj.face4_id = reader.read_node_int()? as i32,
                    _ => reader.skip_to_end()?,
                },
            }
        }
        Ok(obj)
    }
}

